);
-- No selfie, no ID image, no face template, no embedding column. Ever.

alter table kyc.verifications enable row level security;
alter table kyc.verifications force row level security;
-- Users may see their own status only (not scores): expose via a view or RPC, not the raw table.
create policy "own status" on kyc.verifications
  for select to authenticated using ((select auth.uid()) = user_id);

-- Data inventory record (s17)
insert into privacy.data_inventory
  (data_store, fields, data_subjects, purpose, lawful_basis, special_pi, retention, retention_trigger, operators, cross_border, owner)
values
  ('kyc.verifications', '{method,vendor_ref,status,match_band,liveness_passed}', 'customers',
   'Verify that the person opening the account is the holder of the ID document',
