// app/api/kyc/session/route.ts: create a vendor session. API key server-side only.
import { NextResponse } from 'next/server';
import { requireUser, db, hasCurrentConsent, isAdult } from '@/lib/server';

export async function POST() {
  const user = await requireUser();
  if (!(await hasCurrentConsent(user.id, 'special_pi_biometric'))) {
    return NextResponse.json({ error: 'consent_required' }, { status: 403 });
  }
  if (!(await isAdult(user.id))) {                      // s34/s35: no biometrics for minors on an 18+ product
    return NextResponse.json({ error: 'not_eligible' }, { status: 403 });
  }

  const res = await fetch(`${process.env.KYC_API_BASE}/sessions`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${process.env.KYC_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      reference: crypto.randomUUID(),                   // opaque ref, not the user's email or ID number
      checks: ['document', 'face_match', 'liveness'],
      // Set the vendor's retention/deletion options here if the API supports them,
      // e.g. data_retention: 'delete_after_decision', use_for_training: false
    }),
  });
  if (!res.ok) return NextResponse.json({ error: 'vendor_unavailable' }, { status: 502 });
  const session = await res.json();

  await db.kyc.verifications.insert({
    user_id: user.id, method: 'biometric_face_match', vendor: 'vendor_x', vendor_ref: session.id, status: 'pending',
  });
  return NextResponse.json({ sessionToken: session.client_token }); // short-lived; no API key, no PI
}
```

```ts
// app/api/kyc/webhook/route.ts: receive the result. Verify the signature, store only the outcome.
import { NextResponse } from 'next/server';
import { createHmac, timingSafeEqual } from 'crypto';
import { db, queueHumanReview, requestVendorDeletion } from '@/lib/server';

export async function POST(req: Request) {
  const raw = await req.text();
  const sig = req.headers.get('x-signature') ?? '';
  const expected = createHmac('sha256', process.env.KYC_WEBHOOK_SECRET!).update(raw).digest('hex');
  if (sig.length !== expected.length || !timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
    return new NextResponse('Invalid signature', { status: 401 });
  }

  const evt = JSON.parse(raw);
  // Ignore any image URLs or embeddings in the payload. Do not log the payload.
  const band = evt.face_match_score >= 0.9 ? 'high' : evt.face_match_score >= 0.7 ? 'medium' : 'low';
  const passed = band === 'high' && evt.liveness === 'passed' && evt.document === 'valid';

  // s71: only a clear pass is automated. Anything else goes to a person.
  const status = passed ? 'passed' : 'needs_review';
  await db.kyc.verifications.updateByVendorRef(evt.session_id, {
    status, match_band: band, liveness_passed: evt.liveness === 'passed',
    decision_mode: passed ? 'automated' : null, completed_at: new Date().toISOString(),
  });
  if (!passed) await queueHumanReview(evt.session_id);

  // s14: ask the vendor to delete images and templates now, and record it.
  await requestVendorDeletion(evt.session_id);
  await db.kyc.verifications.updateByVendorRef(evt.session_id, { vendor_deletion_requested_at: new Date().toISOString() });

  return NextResponse.json({ ok: true });
}
```

Adjust the field names to your vendor's API and set your thresholds with the vendor's guidance. The point is the shape: pass automatically only on a clear result; everything else is reviewed by a person who can see the ID document through the vendor's dashboard and can approve, request a retry, or move the user to the non-biometric route.

## 4. Other places this touches

- **Environment:** `KYC_API_KEY` and `KYC_WEBHOOK_SECRET` in server env only. Never `NEXT_PUBLIC_*`.
- **Headers:** allow the camera only on the verification page: `Permissions-Policy: camera=(self "https://<vendor-sdk-domain>")` there, `camera=()` everywhere else. Add the vendor's SDK domain to your CSP.
- **Logs and error tracking:** don't log webhook payloads, and make sure Sentry or similar isn't capturing request bodies on these routes.
- **Session replay and analytics:** block the verification pages from Hotjar/Clarity/PostHog replay entirely.
- **Withdrawal:** if a user withdraws biometric consent, stop any pending check, request vendor deletion, and offer the alternative route. The stored pass/fail result can stay if you have another basis (e.g. FICA records); say so in the notice.
- **Account deletion:** include the vendor deletion request in your deletion pipeline.
- **Privacy notice:** add a section on identity verification: what's collected, the vendor and its country, what's kept and for how long, the alternative route, and the right to object and to complain to the Information Regulator (s18).
- **ROPA:** add the vendor with operator agreement status, hosting country, s72 basis, and the s57 position.

## Vendor due-diligence questions to send before signing

1. Where are selfies, ID images, liveness video and face templates processed and stored? Which sub-processors?
2. How long is each kept? Can we set immediate deletion after the decision? Is deletion confirmed by API?
3. Are our users' images or templates used to train or improve your models? Can we opt out contractually?
4. Will you sign an operator agreement that meets POPIA s21 (security measures, breach notification to us, deletion on instruction)?
5. Do you hold ISO 27001 / SOC 2? Most recent penetration test date?
6. What are your false match and false non-match rates, broken down by skin tone, age and gender? What do you recommend for review thresholds?
7. If you check ID numbers against Home Affairs or other sources, under what authorisation?

Once you've answered decisions 1 to 7 at the top (especially which vendor and whether biometrics are required), I'll tailor the code to that vendor's SDK and webhook format.

Note: this is engineering and compliance guidance, not legal advice. The project behind this skill has no legal reviewer yet, and biometric processing, possible cross-border transfer of special personal information, and possible prior authorisation are all cases where you should have a POPIA attorney review the plan before launch.

The newsletter form is now wired to Supabase and Mailchimp. I've kept it lean, but a newsletter is direct marketing by email, so POPIA s69 requires a few things that aren't optional. I've built them in:

- **Explicit opt-in.** An unticked checkbox with wording substantially similar to Form 4 (who you are, what you'll send, which channel). Opt-out is not consent.
- **A consent record stored as evidence**, because the burden of proof is on you (s11(2)(a)).
- **Double opt-in through Mailchimp.** Contacts start as `pending`, so nobody can sign up someone else's address.
- **Unsubscribes flow back to Supabase** (s69(4), s11(3)).
- **Locked-down table.** RLS is on with no client reads, and the service-role key stays on the server.

