```ts
import { createClient } from '@supabase/supabase-js';
import crypto from 'node:crypto';
import { CONSENT_WORDING } from '@/components/Newsletter';

// Server-only env. Never NEXT_PUBLIC_*.
const supabase = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, {
  auth: { persistSession: false },
});
const MC_KEY = process.env.MAILCHIMP_API_KEY!;
const MC_LIST = process.env.MAILCHIMP_LIST_ID!;
const MC_DC = MC_KEY.split('-')[1];

export async function POST(req: Request) {
  const form = await req.formData();
  const email = String(form.get('email') ?? '').trim().toLowerCase();
  const consent = form.get('marketing_consent') === 'yes';
  const version = String(form.get('consent_version') ?? '');

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254) {
    return new Response('Invalid email', { status: 400 });
  }
  if (!consent) return new Response('Consent required to subscribe', { status: 400 }); // s69: no opt-in, no list

  // TODO: add Cloudflare Turnstile / rate limiting here (public endpoint)

  const { data: sub, error } = await supabase
    .from('newsletter_subscribers')
    .upsert({ email, status: 'pending', unsubscribed_at: null }, { onConflict: 'email' })
    .select('id')
    .single();
  if (error) {
    console.error('newsletter upsert failed', { code: error.code }); // no email in logs
    return new Response('Something went wrong', { status: 500 });
  }

  const ip = req.headers.get('x-forwarded-for')?.split(',')[0] ?? '';
  await supabase.schema('privacy').from('consent_events').insert({
    subject_id: sub.id,
    purpose: 'marketing_email_newsletter',
    action: 'granted',
    notice_version: version,
    wording: CONSENT_WORDING,
    channel: 'web_form',
    source_url: req.headers.get('referer'),
    ip_hash: ip ? crypto.createHash('sha256').update(ip + process.env.IP_SALT).digest('hex') : null,
    user_agent: req.headers.get('user-agent'),
  });

  // Double opt-in: 'pending' makes Mailchimp send the confirmation email.
  const hash = crypto.createHash('md5').update(email).digest('hex'); // Mailchimp's subscriber key format, not security
  const mc = await fetch(`https://${MC_DC}.api.mailchimp.com/3.0/lists/${MC_LIST}/members/${hash}`, {
    method: 'PUT',
    headers: { Authorization: `Basic ${Buffer.from(`any:${MC_KEY}`).toString('base64')}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ email_address: email, status_if_new: 'pending', status: 'pending' }), // send only the email
  });
  if (!mc.ok) console.error('mailchimp sync failed', { status: mc.status });

  return Response.redirect(new URL('/newsletter/check-your-inbox', req.url), 303); // no email in the URL
}
```

### 4. `app/api/mailchimp-webhook/route.ts` (handles confirmations and unsubscribes)

```ts
import { createClient } from '@supabase/supabase-js';
const supabase = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false } });

export async function GET() { return new Response('ok'); } // Mailchimp validates the URL with GET

export async function POST(req: Request) {
  // Register the webhook URL as /api/mailchimp-webhook?secret=... and check it
  if (new URL(req.url).searchParams.get('secret') !== process.env.MAILCHIMP_WEBHOOK_SECRET) {
    return new Response('Forbidden', { status: 403 });
  }
  const f = await req.formData();
  const type = f.get('type');
  const email = String(f.get('data[email]') ?? '').toLowerCase();

  if (type === 'subscribe') {
    await supabase.from('newsletter_subscribers').update({ status: 'subscribed' }).eq('email', email);
  }
  if (type === 'unsubscribe' || type === 'cleaned') {
    const { data } = await supabase.from('newsletter_subscribers')
      .update({ status: 'unsubscribed', unsubscribed_at: new Date().toISOString() })
      .eq('email', email).select('id').single();
    if (data) await supabase.schema('privacy').from('consent_events').insert({
      subject_id: data.id, purpose: 'marketing_email_newsletter', action: 'withdrawn',
      notice_version: 'n/a', wording: 'Unsubscribed via Mailchimp', channel: 'mailchimp_webhook',
    });
  }
  return new Response('ok');
}
```

